package android.os;
public final class Bundle {private final java.util.Map<String,Object> values=new java.util.HashMap<>();public CharSequence getCharSequence(String key){Object v=values.get(key);return v instanceof CharSequence?(CharSequence)v:null;}public void putCharSequence(String key,CharSequence value){values.put(key,value);}public boolean getBoolean(String key,boolean fallback){Object v=values.get(key);return v instanceof Boolean?(Boolean)v:fallback;}public void putBoolean(String key,boolean value){values.put(key,value);}}
